import {courseLesson,edit} from './utility-authoring.js';
const L=(...args)=>courseLesson("time",...args);
export const timeUtilsLessons=[
L("duration","Turn seconds into readable durations",[6, 7, 13],"<p>A duration is an amount of time, not an absolute date. <code>dhms()</code> uses colon-separated fields; <code>english_time()</code> uses words. Supply a reference date for month/year calculations. Parse units explicitly rather than assuming every month has the same duration.</p>","seconds = 3661;\nplayer:tell(\"DHMS: \", toliteral($time_utils:dhms(seconds)));\nplayer:tell(\"ENGLISH: \", toliteral($time_utils:english_time(seconds, \"Thu Jan 01 00:00:00 1970 UTC\")));\nplayer:tell(\"PARSED seconds: \", toliteral($time_utils:parse_english_time_interval(\"1 hour and 1 minute\")));",edit("seconds = 3661;","seconds = 61;","Reduce the duration to 61 seconds. Both formatters now describe one minute and one second.")),
L("seconds","Convert a clock and a full date",[3, 5],"<p>A clock string gives seconds since midnight; a full ctime-style string identifies an instant using its timezone. <code>from_ctime()</code> returns an error value for malformed input. Include the timezone; the legacy five-word form assumes PST.</p>","clock = \"01:02:03\";\nplayer:tell(\"CLOCK seconds: \", toliteral($time_utils:to_seconds(clock)));\nplayer:tell(\"EPOCH instant: \", toliteral($time_utils:from_ctime(\"Thu Jan 01 00:00:00 1970 GMT\")));\nplayer:tell(\"INVALID date: \", toliteral($time_utils:from_ctime(\"not a date\")));",edit("clock = \"01:02:03\";","clock = \"02:02:03\";","Increase the hour by one. The clock total increases by 3,600 seconds.")),
L("weekday","Extract weekday, month and time",[0, 1, 2],"<p>The string overload reads a ctime-style date directly, so the example does not depend on your machine\u2019s timezone. <code>ampm()</code> accepts precision 1, 2 or 3 for hours, minutes or seconds.</p>","date = \"Tue Mar 05 13:04:09 2024 UTC\";\nplayer:tell(\"DAY: \", toliteral($time_utils:day(date)));\nplayer:tell(\"MONTH: \", toliteral($time_utils:month(date)));\nplayer:tell(\"AMPM minutes: \", toliteral($time_utils:ampm(date, 2)));\nplayer:tell(\"AMPM seconds: \", toliteral($time_utils:ampm(date, 3)));",edit("13:04:09","00:04:09","Change the clock to shortly after midnight. AM/PM changes from afternoon to 12 a.m.")),
L("date-order","Choose an explicit date order",[12, 17],"<p>The called alias selects month-first or day-first output. Prefer four-digit years for clarity, and label the order because dates like 03/05 are ambiguous without context. The optional separator changes punctuation, not ordering.</p>","date = \"Tue Mar 05 13:04:09 2024 UTC\";\nplayer:tell(\"MMDDYY: \", toliteral($time_utils:mmddyy(date)));\nplayer:tell(\"DDMMYY: \", toliteral($time_utils:ddmmyy(date)));\nplayer:tell(\"MMDDYYYY: \", toliteral($time_utils:mmddyyyy(date, \"-\")));\nplayer:tell(\"DDMMYYYY: \", toliteral($time_utils:ddmmyyyy(date, \"-\")));",edit("2024 UTC","2025 UTC","Change the year to 2025. Both short and full year formats update.")),
L("templates","Format an instant with time macros",[11, 16],"<p>Time templates distinguish uppercase and lowercase macros: <code>$Y</code> is the full year, <code>$y</code> the short year. The date is interpreted in the server timezone. This example uses the Unix epoch and a UTC native fixture; a differently configured server may display another local date.</p>","instant = 0;\nplayer:tell(\"TEMPLATE year: \", toliteral($time_utils:time_sub(\"Year $Y\", instant)));\nplayer:tell(\"RFC822 date: \", toliteral($time_utils:rfc822_ctime(instant)));",edit("instant = 0;","instant = 86400;","Advance one day. The formatted RFC date advances to January 2 in the UTC fixture; the year remains 1970.")),
L("calendar","Understand historical calendar assumptions",[8, 9, 10, 14, 15],"<p>These legacy calendar helpers contain PST/PDT assumptions. <code>from_day()</code> accepts a reference instant, but <code>from_month()</code> and the countdown helpers read the live clock. Negative countdowns mean the selected time has passed today; they are not automatically tomorrow. <code>dst_midnight()</code> depends on the server timezone. Values below vary.</p>","reference = 1704067200;\nplayer:tell(\"FROM DAY next Monday: \", toliteral($time_utils:from_day(\"Monday\", 1, reference)));\nplayer:tell(\"FROM MONTH next January: \", toliteral($time_utils:from_month(\"January\", 1)));\nplayer:tell(\"DST MIDNIGHT: \", toliteral($time_utils:dst_midnight(reference)));\nplayer:tell(\"UNTIL DATE: \", toliteral($time_utils:seconds_until_date(\"January\", 1, \"12:00:00\", 1)));\nplayer:tell(\"UNTIL TIME noon: \", toliteral($time_utils:seconds_until_time(\"12:00:00\")));",edit("\"12:00:00\"","\"13:00:00\"","Move the target clock forward one hour. The time-of-day countdown increases by about 3,600 seconds; live execution time can affect the exact difference."),{"experimentDelta":{"prefix":"UNTIL TIME noon: ","delta":3600,"tolerance":5},"outputChoices": {"FROM MONTH next January: ": {"kind": "number", "min": 0, "max": 100000000000, "integer": true}, "UNTIL DATE: ": {"kind": "number", "min": -100000000, "max": 100000000, "integer": true}, "UNTIL TIME noon: ": {"kind": "number", "min": -86400, "max": 86400, "integer": true}}}),
L("timer-report","Build a duration report",[],"<p>Parse the requested interval once, then reuse the numeric duration for calculations and display. A human-readable description is output, not a replacement for the integer seconds.</p>","request = \"2 minutes and 30 seconds\";\nseconds = $time_utils:parse_english_time_interval(request);\nplayer:tell(\"REQUEST: \", toliteral(request));\nplayer:tell(\"SECONDS: \", toliteral(seconds));\nplayer:tell(\"DISPLAY: \", toliteral($time_utils:dhms(seconds)));",edit("2 minutes","3 minutes","Request three minutes and thirty seconds. The stored duration becomes 210 and the display becomes 3:30.")),
];
export const timeExclusions={"4": "Legacy site-specific solar calculation uses fixed-point trigonometry and location calibration properties. Retained in Reference rather than taught as a portable date/time API."};
